/** 本层统一注入的默认线宽，见 tokens.ts 的注释。 */
const DEFAULT_STROKE = 2;

/**
 * 包装一个有默认线宽的图标。
 *
 * 只做一件事：`strokeWidth` 缺省时补 2。调用方显式传值时不覆盖，
 * 所以需要更细或更重的场景仍然可控。
 */
function wrap(
  Raw: React.ComponentType<Record<string, unknown>>,
  name: string,
): React.ComponentType<Record<string, unknown>> {
  const Wrapped = (props: Record<string, unknown>) =>
    createElement(Raw, { strokeWidth: DEFAULT_STROKE, ...props });
  Wrapped.displayName = name;
  return Wrapped;
}

