/* 下面这些图标在组件里被使用，但不在「默认线宽 2」的包装集合内。
 * 直接透出上游版本（线宽 1.5），与本仓库 index.ts 的 export * 行为一致。 */
export { QiArrowCornerDownLeft } from "qingicon-react";
export { QiCharMinus } from "qingicon-react";
export { QiFile } from "qingicon-react";
export { QiFolder3 } from "qingicon-react";

/* 包装层的契约：线宽、尺寸、语义色与图标类型。组件直接依赖，必须一起下发。 */
export * from "./icon-tokens";

export type QIconComponent = React.ComponentType<{
  className?: string;
  strokeWidth?: number | string;
  optical?: boolean;
  "aria-hidden"?: boolean | "true" | "false";
}>;

/**
 * QingIcon 公共库 —— 设计令牌与用法契约
 *
 * 这个文件只放「跨组件库共用、且需要统一口径」的常量，不放任何图标本身。
 * 三个消费方（QiguanUI、Arc UI、独立 HTML 页面）都从这里取同一份数值，
 * 避免各自写一套导致同一排图标粗细不一致。
 */

/** 图标组件的公共 Props —— 与 `qingicon-react` 的 IconProps 取交集后的稳定子集。 */
export interface QIconProps {
  /** 尺寸。优先用 className 的 size-* 控制；传数值时单位为 px。 */
  size?: number | string;
  /** 颜色。建议不传，用 className 的 text-* 语义色走 currentColor。 */
  color?: string;
  /** 描边宽度，见 QICON_STROKE。 */
  strokeWidth?: number | string;
  /** 小尺寸下自动加粗描边，保持视觉重量。 */
  optical?: boolean;
  className?: string;
  style?: React.CSSProperties;
  "aria-hidden"?: boolean | "true" | "false";
  "aria-label"?: string;
}

/**
 * 描边宽度。
 *
 * 实测差异（不是推测）：`qingicon-react` 的默认 strokeWidth 是 1.5，
 * 而 `@remixicon/react` 是 2。两者并排时 QingIcon 视觉上会轻约 25%。
 *
 * 因为本次要求「与原图标视觉尽量一致」，默认取 `default`（= 2）对齐
 * 原 Remix 口径；只有在整屏都是 QingIcon、需要其原生轻盈感时才用 `native`。
 */
export const QICON_STROKE = {
  /** QingIcon 上游原始默认 */
  native: 1.5,
  /** 与原 @remixicon/react 对齐（本库默认） */
  default: 2,
  /** 更重的语义强调场景 */
  bold: 2.5,
} as const;

/**
 * 常用尺寸。
 *
 * 与 QiguanUI 现有 Tailwind 类一一对应，供不能写 className 的场景
 * （如 canvas 绘制、SVG 字符串拼接、Arco 的 icon 传参）取值用。
 *
 *   size-3   = 12px   → 表格行内辅助标记
 *   size-3.5 = 14px   → 紧凑文字旁的图标
 *   size-4   = 16px   → 默认行内图标（最常用）
 *   size-[18px] = 18px → 按钮内图标
 *   size-5   = 20px   → 导航、工具条
 *   size-6   = 24px   → 空状态、卡片主图标
 */
export const QICON_SIZE = {
  xs: 12,
  sm: 14,
  md: 16,
  lg: 18,
  xl: 20,
  "2xl": 24,
  "3xl": 32,
} as const;

/**
 * 语义色类名映射。
 *
 * 图标颜色一律走 `currentColor`，所以「给图标上色」= 给它的 className 加
 * 一个 text-* 类。这里把 QiguanUI 现用的语义 token 收成一份清单，
 * 供代码审查与迁移脚本核对，避免有人退回 `text-gray-500` 这类字面色。
 */
export const QICON_TONE = {
  primary: "text-foreground-icon-primary",
  secondary: "text-foreground-icon-secondary",
  tertiary: "text-foreground-icon-tertiary",
  quaternary: "text-foreground-icon-quaternary",
  brand: "text-brand",
  danger: "text-danger",
  success: "text-success",
  warning: "text-warning",
  info: "text-information",
} as const;

export type QICON_TONE_KEY = keyof typeof QICON_TONE;

/** 尺寸键 → Tailwind 类名。18px 没有内置刻度，用任意值写法。 */
const SIZE_CLASS: Record<keyof typeof QICON_SIZE, string> = {
  xs: "size-3",
  sm: "size-3.5",
  md: "size-4",
  lg: "size-[18px]",
  xl: "size-5",
  "2xl": "size-6",
  "3xl": "size-8",
};

/** 生成一个图标的 className：尺寸 + 语义色 + 可选附加类。 */
export function qiconClass(
  size: keyof typeof QICON_SIZE = "md",
  tone?: QICON_TONE_KEY,
  extra?: string,
): string {
  return [SIZE_CLASS[size], tone ? QICON_TONE[tone] : "", extra ?? ""]
    .filter(Boolean)
    .join(" ");
}
